import type { Question } from '../questions';

export const OPSC_OCS_2025_PRELIMS_GS_2_CSAT_FULL_1: Question[] = [
  { id: 'b15-003-csat-q001', section: 'General Studies Paper II (CSAT)', topic: 'Averages', difficulty: 'easy', question: 'A driver makes three trips of 20 km, 30 km and 50 km using 2, 3 and 5 litres of fuel respectively. What is the average distance per litre over all trips?', options: ['9 km/litre', '10 km/litre', '11 km/litre', '12.5 km/litre'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Total distance =100 km and total fuel =10 litres, so overall average =10 km/litre.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q002', section: 'General Studies Paper II (CSAT)', topic: 'Coding-decoding', difficulty: 'medium', question: 'In a code, letters in odd positions move one step forward and letters in even positions move one step backward in the alphabet. What is the code for MATH?', options: ['LZSG', 'NZTH', 'NZUG', 'MBUH'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'M→N, A→Z, T→U, H→G, giving NZUG.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q003', section: 'General Studies Paper II (CSAT)', topic: 'Divisibility and digits', difficulty: 'medium', question: 'A three-digit code has digits whose sum is 15. The code is divisible by 9 only if its digit sum is divisible by 9. Which statement is correct about this code?', options: ['It must be divisible by 9.', 'It cannot be divisible by 3.', 'It must be divisible by 3 but not necessarily by 9.', 'It must end in 5.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A digit sum of 15 is divisible by 3 but not by 9, so the number is divisible by 3 and not divisible by 9.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q004', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A clinic noticed that patients often arrived without one required document. It added the document list to appointment messages. Staff then spent less time explaining missing-document requirements at the desk.\n\nWhat is the central idea?', options: ['Appointment messages should contain no practical information.', 'Giving requirements before a visit can prevent avoidable clarification at the service point.', 'The clinic removed the document requirement.', 'Desk staff became unnecessary after the change.'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The passage links advance information about requirements with less repeated explanation at the desk.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q005', section: 'General Studies Paper II (CSAT)', topic: 'Algebra', difficulty: 'easy', question: 'Solve for x: 3(x − 4) + 5 = 26.', options: ['11', '9', '7', '13'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: '3x−12+5=26, so 3x−7=26, 3x=33 and x=11.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q006', section: 'General Studies Paper II (CSAT)', topic: 'Arrangement', difficulty: 'hard', question: 'During a coastal service-delivery review, Five books A, B, C, D and E are on a shelf. A is immediately left of B, and D is immediately right of E. Which pair must stay adjacent in every valid arrangement? The field team must reach the answer from these facts alone.', options: ['A and B', 'A and C', 'B and D', 'C and E'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The first rule explicitly requires A immediately beside B; the other pairings are not forced.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q007', section: 'General Studies Paper II (CSAT)', topic: 'Decision making', difficulty: 'hard', question: 'An inspection officer discovers a minor form error that does not affect the safety finding and can be corrected transparently. The rules allow documented clerical corrections. What should be done?', options: ['Rewrite the safety finding to conceal the error.', 'Destroy the original inspection record.', 'Ignore the correction procedure because the error is minor.', 'Correct the clerical error through the documented correction process without changing the substantive finding.'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The rules provide a transparent correction mechanism, so the clerical defect should be fixed without altering substantive evidence.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q008', section: 'General Studies Paper II (CSAT)', topic: 'Simple interest', difficulty: 'easy', question: 'Two simple-interest deposits of ₹5,000 each are made for 3 years, one at 6% and one at 8%. How much more interest does the second earn?', options: ['₹100', '₹200', '₹600', '₹300'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Rate difference is 2%; extra interest=5000×2×3/100=₹300.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q009', section: 'General Studies Paper II (CSAT)', topic: 'Sequence of events', difficulty: 'medium', question: 'A permit process requires verification before approval, and payment only after approval. Which sequence is valid?', options: ['Verification → Approval → Payment', 'Payment → Verification → Approval', 'Approval → Payment → Verification', 'Verification → Payment → Approval'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The two stated precedence rules force verification first, approval second and payment last.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q010', section: 'General Studies Paper II (CSAT)', topic: 'Mensuration', difficulty: 'medium', question: 'A rectangular inspection board has a perimeter of 58 cm. Its length is 5 cm more than its width. What is the width of the board?', options: ['10 cm', '12 cm', '14 cm', '17 cm'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Let the width be w cm, so the length is w + 5. Then 2[(w + 5) + w] = 58, giving 4w + 10 = 58 and w = 12 cm.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q011', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A village water committee recorded pump failures for six months. Most failures followed voltage fluctuations, so the committee installed a stabilizer before replacing the pump. Failures then became less frequent.\n\nWhy was the stabilizer a reasonable first intervention?', options: ['A stabilizer always repairs a damaged pump.', 'The committee had proved that no other cause was possible.', 'The records pointed to unstable voltage as a recurring condition associated with failures.', 'Replacing the pump would have increased voltage fluctuations.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The committee used its own failure records to address a recurring associated condition before choosing the more drastic replacement.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q012', section: 'General Studies Paper II (CSAT)', topic: 'Mensuration', difficulty: 'medium', question: 'A cylindrical drum has radius 0.5 m and height 1.2 m. Using π≈3.14, what is its volume?', options: ['0.471 m³', '0.942 m³', '1.884 m³', '3.768 m³'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Volume =πr²h=3.14×0.25×1.2=0.942 m³.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q013', section: 'General Studies Paper II (CSAT)', topic: 'Scheduling', difficulty: 'hard', question: 'Four inspections J, K, L and M must be scheduled one at a time. K must be immediately after J, and M must occur before L. Which order satisfies both conditions?', options: ['J, M, K, L', 'K, J, M, L', 'M, J, K, L', 'J, K, L, M'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'M, J, K, L places K immediately after J and also places M before L. Each other option violates at least one condition.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q014', section: 'General Studies Paper II (CSAT)', topic: 'Classification', difficulty: 'easy', question: 'Which item does not belong with the others on the basis of number type?', options: ['27', '16', '25', '36'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: '16, 25 and 36 are perfect squares; 27 is not.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q015', section: 'General Studies Paper II (CSAT)', topic: 'Counting', difficulty: 'medium', question: 'A committee of 2 is chosen from 5 people, but A and B cannot serve together. How many committees are possible?', options: ['8', '9', '10', '12'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'There are C(5,2)=10 pairs in all; exclude the one pair A-B, leaving 9.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q016', section: 'General Studies Paper II (CSAT)', topic: 'Problem solving', difficulty: 'medium', question: 'Four files A, B, C and D must be reviewed. B must be before D; C must be after A; D must be after C. Which order is valid?', options: ['A, C, B, D', 'B, D, A, C', 'C, A, B, D', 'A, D, C, B'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A before C and C before D are required, with B before D. Only A, C, B, D satisfies all three constraints.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q017', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension and mechanism', difficulty: 'medium', question: 'A vegetable nursery covered half of its seedling beds with a porous shade net during a hot spell. The covered beds had lower midday soil temperatures and required less irrigation, while morning sunlight still reached the seedlings.\n\nWhich explanation best fits the observations?', options: ['The net increased midday solar heating.', 'The net stopped all light and all evaporation.', 'The net reduced peak heat load and evaporation without eliminating useful light.', 'The net made irrigation water evaporate faster.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Lower soil temperature and reduced irrigation need, while morning light still enters, are consistent with reduced peak radiation and evaporation rather than complete darkness.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q018', section: 'General Studies Paper II (CSAT)', topic: 'Quantitative reasoning', difficulty: 'hard', question: 'An amount is split so that the larger part is ₹240 more than the smaller and is 1.5 times the smaller. What is the total amount?', options: ['₹960', '₹1,200', '₹1,080', '₹1,440'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'If smaller=s, then 1.5s−s=240, so s=480, larger=720, total=1,200.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q019', section: 'General Studies Paper II (CSAT)', topic: 'Percentages', difficulty: 'easy', question: 'A survey response rate moves from 48% to 60%. By how many percentage points did it increase?', options: ['25 percentage points', '8 percentage points', '20 percentage points', '12 percentage points'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Percentage-point change is 60−48=12.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q020', section: 'General Studies Paper II (CSAT)', topic: 'Interpersonal skills', difficulty: 'medium', question: 'A colleague repeatedly interrupts another during meetings. Which response is most constructive?', options: ['Interrupt the colleague even more often.', 'Exclude the colleague from every future meeting without discussion.', 'Set a discussion rule that each speaker finishes before responses, and enforce it consistently.', 'Pretend the pattern has no effect on participation.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A clear, neutral participation rule addresses the behavior without turning the issue into a personal contest.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q021', section: 'General Studies Paper II (CSAT)', topic: 'Problem solving', difficulty: 'hard', question: 'A generator can power either two pumps or one pump plus the communication tower. During a flood, at least one pump and the tower must operate. Which allocation satisfies the requirement?', options: ['Two pumps only', 'The communication tower only', 'No equipment until full power returns', 'One pump and the communication tower'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The stated minimum requires both a pump and the tower; the mixed allocation is the only listed one that does so.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q022', section: 'General Studies Paper II (CSAT)', topic: 'Spatial reasoning', difficulty: 'medium', question: 'A point starts at (2,1), moves 3 units east, 4 units north, then 1 unit west. What are its final coordinates?', options: ['(6,5)', '(4,5)', '(4,3)', '(0,5)'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: '(2,1)→(5,1)→(5,5)→(4,5).', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q023', section: 'General Studies Paper II (CSAT)', topic: 'Ages', difficulty: 'medium', question: 'Five years ago, Arun was twice Bela\'s age. In five years, their ages will sum to 50. What is Bela\'s current age?', options: ['10 years', '15 years', '12 years', '20 years'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Let current ages A,B. A−5=2(B−5) and A+B+10=50. So A+B=40 and A=2B−5, giving 3B=45, B=15.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q024', section: 'General Studies Paper II (CSAT)', topic: 'Constraint reasoning', difficulty: 'medium', question: 'A four-bit status code abcd must satisfy both conditions a=d and b≠c. Which code is valid?', options: ['0100', '0110', '1100', '0011'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'For 0100, the first and fourth bits are both 0, while the second and third bits are 1 and 0, so both conditions hold. Each other option violates at least one condition.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q025', section: 'General Studies Paper II (CSAT)', topic: 'Probability', difficulty: 'easy', question: 'Two fair coins are tossed. What is the probability of getting exactly one head?', options: ['1/4', '1/2', '3/4', '1/3'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Outcomes HH, HT, TH, TT are equally likely; exactly one head occurs in HT and TH, 2 of 4.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q026', section: 'General Studies Paper II (CSAT)', topic: 'Speed, distance and time', difficulty: 'medium', question: 'A runner increases speed from 8 m/s to 10 m/s for a 400 m segment. How much time is saved?', options: ['5 seconds', '8 seconds', '20 seconds', '10 seconds'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Times are 50 s and 40 s, so 10 s are saved.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q027', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension and process design', difficulty: 'medium', question: 'A scholarship portal began pre-filling applicants\' district and school codes from a verified database, while leaving applicants free to correct any mismatch before submission. Rejections caused by mistyped codes fell sharply, but rejections for missing income documents did not change.\n\nWhat is the strongest inference?', options: ['Pre-filling eliminated every application error.', 'Verified pre-fill specifically reduced code-entry mistakes, not unrelated documentation omissions.', 'Applicants no longer needed to review their forms.', 'Missing income documents were caused by wrong school codes.'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Only code-related rejections fell, while unrelated document omissions were unchanged; the evidence supports a targeted reduction in code-entry errors.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q028', section: 'General Studies Paper II (CSAT)', topic: 'Data interpretation', difficulty: 'medium', question: 'A help desk handled 120 email requests and 80 phone requests in a day. Of these, 90 email requests and 52 phone requests were resolved the same day. What percentage of all requests were resolved the same day?', options: ['68%', '69%', '70%', '71%'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Same-day resolutions = 90+52 = 142 out of 200 total requests. 142/200 = 71%.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q029', section: 'General Studies Paper II (CSAT)', topic: 'Communication skills', difficulty: 'easy', question: 'A technical circular contains a new rule, its effective date and a long background history. Field staff mainly need to know what changes tomorrow. What is the best opening?', options: ['State the new rule and effective date first, then provide background below.', 'Begin with the oldest historical detail and reveal the rule at the end.', 'Omit the effective date.', 'Replace the rule with an unexplained acronym.'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Action-critical information should appear before supporting background when readers must act quickly.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q030', section: 'General Studies Paper II (CSAT)', topic: 'Communication skills', difficulty: 'hard', question: 'Two departments use different meanings for the term \'closed case\'. What should a joint dashboard do before comparing their closure rates?', options: ['Average the two rates without checking definitions.', 'Choose whichever definition produces the larger rate.', 'Define a common closure rule and map each department\'s records to that definition.', 'Remove all labels from the dashboard.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Comparable reporting requires the same underlying definition; otherwise identical labels can hide different measures.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q031', section: 'General Studies Paper II (CSAT)', topic: 'Data sufficiency', difficulty: 'hard', question: 'Is n greater than 20?\nI. n is an integer greater than 18.\nII. n is an odd integer less than 24.', options: ['Statement I alone is sufficient.', 'Statement II alone is sufficient.', 'Even together, the statements are not sufficient.', 'Both statements together are sufficient, but neither alone is sufficient.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Together n can be 19, 21 or 23, so the answer to whether n>20 is not determined.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q032', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension and measurement', difficulty: 'hard', question: 'A district training programme compared two batches using the same final test. Batch A had attended an optional practice clinic that was mostly used by weaker trainees. Batch A\'s average final score was lower than Batch B\'s. The coordinator refused to conclude that the clinic harmed learning.\n\nWhy is that caution justified?', options: ['Average scores can never be compared across batches.', 'Optional clinics always improve every participant.', 'Final tests contain no useful information.', 'The clinic users may have differed systematically from non-users before the clinic, so the raw averages do not isolate the clinic\'s effect.'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Self-selection by weaker trainees creates a baseline difference; comparing raw final averages alone does not identify the causal effect of the clinic.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q033', section: 'General Studies Paper II (CSAT)', topic: 'Mensuration', difficulty: 'medium', question: 'A survey trolley wheel has radius 0.35 m. It rolls without slipping for 440 m. Using π = 22/7, how many complete revolutions does the wheel make?', options: ['200', '220', '180', '140'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'One revolution covers the wheel\'s circumference: 2πr = 2×(22/7)×0.35 = 2.2 m. Hence the number of revolutions is 440/2.2 = 200.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q034', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A property-tax portal began showing each taxpayer the amount due, payment status, due date and a receipt-download link. Calls asking “Has my payment been received?” fell sharply, while calls about disputed assessments continued at about the same level.\n\nWhich inference is most strongly supported?', options: ['Residents became less interested in the office.', 'Median closure time necessarily fell because the chart was published.', 'Publishing data always eliminates complaints.', 'Clear routine information can reduce repetitive queries without reducing public engagement.'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Routine status information became easier to obtain, reducing repetitive status calls, while more substantive disputes still generated engagement.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q035', section: 'General Studies Paper II (CSAT)', topic: 'Constraint reasoning', difficulty: 'hard', question: 'Four workshops J, K, L and M occupy four consecutive slots. J must be before L; K cannot be first; M must be immediately after J. Which schedule is possible?', options: ['J, M, K, L', 'K, J, L, M', 'J, K, L, M', 'L, J, M, K'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'J,M must be consecutive in that order and J before L. Only J,M,K,L satisfies all constraints.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q036', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension and rates', difficulty: 'medium', question: 'A road unit repaired 300 potholes in a dry month and 260 in a rainy month. Re-inspection found 12 failures in the dry-month repairs and 13 in the rainy-month repairs. Which comparison is most appropriate?', options: ['The rainy month was better because 260 is smaller than 300.', 'The two months are identical because both had more than 250 repairs.', 'Compare failure rates: 12/300 versus 13/260.', 'Compare only the absolute number of failures and ignore the number repaired.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Because the numbers repaired differ, failure rates provide the meaningful comparison: 4% in the dry month versus 5% in the rainy month.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q037', section: 'General Studies Paper II (CSAT)', topic: 'Ratio and proportion', difficulty: 'easy', question: 'Red and blue files are in the ratio 5:3. After 16 blue files are added, the ratio becomes 5:4. How many red files were there originally?', options: ['60', '64', '100', '80'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Let red=5x, blue=3x. 5x/(3x+16)=5/4 gives 20x=15x+80, so x=16 and red=80.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q038', section: 'General Studies Paper II (CSAT)', topic: 'Decision making and safety', difficulty: 'medium', question: 'A field officer sees that a temporary footbridge has developed a visible structural crack. The maintenance manual says any suspected structural defect requires immediate closure and engineering inspection before reopening. What should the officer do first?', options: ['Close access and request the required engineering inspection.', 'Keep the bridge open until a complaint is received.', 'Paint over the crack to avoid concern.', 'Allow only heavy vehicles to test whether the bridge is safe.'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The stated safety rule requires immediate closure and inspection when a structural defect is suspected.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q039', section: 'General Studies Paper II (CSAT)', topic: 'Profit, loss and discount', difficulty: 'medium', question: 'A seller wants a 20% profit on an item costing ₹750. If the item will be sold after a 10% discount on its marked price, what marked price should be set?', options: ['₹900', '₹1,000', '₹960', '₹1,080'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A 20% profit requires a selling price of ₹900. If this is 90% of marked price, marked price = 900/0.9 = ₹1,000.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q040', section: 'General Studies Paper II (CSAT)', topic: 'Communication skills', difficulty: 'medium', question: 'A meeting decision affects staff who were absent. Which follow-up most reduces later ambiguity?', options: ['Rely on informal retelling by attendees.', 'Send only the meeting date.', 'Send a concise record of the decision, responsible persons, deadlines and any unresolved points.', 'Avoid documenting unresolved points.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A decision record preserves what was decided, who acts, by when, and what remains open.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q041', section: 'General Studies Paper II (CSAT)', topic: 'Data interpretation', difficulty: 'easy', question: 'A table shows units inspected and defects found: Zone A 200/8, B 150/9, C 300/9. Which zone has the lowest defect rate?', options: ['Zone C', 'Zone A', 'Zone B', 'Zones A and C are equal'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Rates: A=4%, B=6%, C=3%; C is lowest.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q042', section: 'General Studies Paper II (CSAT)', topic: 'Process reasoning', difficulty: 'medium', question: 'Three queues start with 2, 5 and 8 cases. In one balancing step, one case is moved from the longest queue to the shortest queue. Two balancing steps are performed, recalculating the longest and shortest queues after each step. What are the queue sizes afterward?', options: ['3, 6, 6', '4, 4, 7', '4, 5, 6', '5, 5, 5'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The first step changes (2, 5, 8) to (3, 5, 7). Recalculating, the second step moves one case from 7 to 3, giving (4, 5, 6).', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q043', section: 'General Studies Paper II (CSAT)', topic: 'Boats and streams', difficulty: 'easy', question: 'A district grievance unit works through this situation. A survey boat moves downstream at 16 km/h and upstream at 12 km/h. What is the boat speed in still water? No local exception beyond the stated conditions applies.', options: ['12', '14', '2', '4'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Still-water speed = (16+12)/2 = 14 and stream speed = (16−12)/2 = 2 km/h.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q044', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'An office tested a new queue token display for one week on a single floor. Waiting-room confusion fell there. Managers decided to test the display on two more floors before adopting it building-wide.\n\nWhat reasoning principle does this decision illustrate?', options: ['A one-week test proves the display will work everywhere.', 'Any change that helps one floor must immediately be compulsory everywhere.', 'A promising local result should be checked in additional settings before broad adoption.', 'Further testing is useful only when the first test fails.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The managers treat the first result as encouraging but not automatically generalizable to the whole building.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q045', section: 'General Studies Paper II (CSAT)', topic: 'Digit reasoning', difficulty: 'medium', question: 'A two-digit number has digit sum 11. Reversing its digits makes the number 27 smaller. What is the number?', options: ['47', '65', '74', '83'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Let number=10a+b. Reversal is 27 smaller: 9(a−b)=27, so a−b=3. With a+b=11, a=7,b=4.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q046', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension and cold-chain management', difficulty: 'medium', question: 'A fish market introduced insulated boxes for vendors who previously stored fish in open trays. Temperature logs showed that boxed fish stayed within the recommended range for longer, while the time from landing to market remained unchanged.\n\nWhat does the evidence most directly show?', options: ['Travel time became shorter.', 'Open trays became colder than insulated boxes.', 'All fish spoilage was eliminated.', 'Insulated storage improved temperature control even though transport time did not change.'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The only changed factor described is storage method; temperature control improved while travel time stayed the same.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q047', section: 'General Studies Paper II (CSAT)', topic: 'Set reasoning', difficulty: 'medium', question: 'No digital-only files are paper originals. Some archived items are digital-only files. Which conclusion follows?', options: ['All archived items are paper originals.', 'No archived item is digital-only.', 'Some archived items are not paper originals.', 'Some paper originals are digital-only files.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The archived items that are digital-only cannot be paper originals.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q048', section: 'General Studies Paper II (CSAT)', topic: 'Compound interest', difficulty: 'medium', question: 'An amount grows from ₹8,000 to ₹9,680 in two years at annual compound interest. What annual rate was used?', options: ['8%', '11%', '12%', '10%'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: '9680/8000=1.21=(1.10)², so the annual rate is 10%.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q049', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension and audit sampling', difficulty: 'hard', question: 'An audit team checks a random sample of invoices from each branch every month. A branch whose sample error rate exceeds 4% receives a full review. One branch had 3 errors in a sample of 50 invoices. What action follows from the stated rule?', options: ['No action, because three errors are always acceptable.', 'Close the branch immediately.', 'Conduct a full review because 3/50 = 6%, which exceeds 4%.', 'Ignore the sample because 50 is too small by definition.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The observed sample error rate is 6%, above the stated 4% threshold, so the rule triggers a full review.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q050', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension and environmental evidence', difficulty: 'medium', question: 'Three coastal wells showed rising salinity during a period of heavy groundwater pumping. After pumping was reduced, salinity fell gradually in the two wells closest to the coast but changed little in the inland well.\n\nWhich inference is best supported?', options: ['The pattern is consistent with coastal pumping contributing to saltwater intrusion in the nearer wells.', 'All groundwater salinity is caused only by rainfall.', 'The inland well must contain seawater.', 'Reducing pumping always makes every well fresh immediately.'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The spatial pattern and partial reversal after reduced pumping are consistent with pumping-related saltwater intrusion in coastal wells, without proving a universal cause.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q051', section: 'General Studies Paper II (CSAT)', topic: 'Interpersonal communication', difficulty: 'medium', question: 'During a planning meeting, two teams use the word \'urgent\' differently: one means \'within 24 hours\' and the other means \'before the weekly review.\' What is the most useful next step?', options: ['Ask both teams to stop using deadlines.', 'State the two interpretations explicitly and agree on a measurable deadline for this task.', 'Adopt one team\'s meaning without discussion.', 'Postpone the task until the teams naturally agree.'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Making the differing meanings explicit and converting \'urgent\' into a measurable deadline removes the ambiguity driving the disagreement.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q052', section: 'General Studies Paper II (CSAT)', topic: 'Logical consistency', difficulty: 'hard', question: 'Three statements are made: (1) Every blue tag is numbered. (2) No numbered tag is temporary. (3) Some blue tags are temporary. Which assessment is correct?', options: ['Only statement 1 can be true.', 'Statements 1 and 3 force every tag to be temporary.', 'The three statements cannot all be true together.', 'The statements are mutually supporting.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'From (1), every blue tag is numbered; from (2), no numbered tag is temporary. Thus no blue tag can be temporary, contradicting (3).', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q053', section: 'General Studies Paper II (CSAT)', topic: 'Classification by rule', difficulty: 'medium', question: 'Three pairs follow the same rule and one does not. Which pair is different?', options: ['3 → 10', '5 → 25', '4 → 17', '6 → 37'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'For 3, 4 and 6, the right side equals n²+1: 10, 17 and 37. For 5, n²+1 would be 26, not 25.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q054', section: 'General Studies Paper II (CSAT)', topic: 'Algebraic constraints', difficulty: 'medium', question: 'Which of the following values of x satisfies both 3x + 2 ≤ 14 and 2x − 1 > 5?', options: ['1', '3', '4', '6'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The first inequality gives x ≤ 4, while the second gives x > 3. The only listed value satisfying both is x = 4.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q055', section: 'General Studies Paper II (CSAT)', topic: 'Quantitative reasoning', difficulty: 'medium', question: 'An inspection priority score is defined as S = 4R + 3A, where R is the risk rating and A is the number of days waiting. Case X has R=5 and A=2; Case Y has R=3 and A=5. Which statement is correct?', options: ['Case Y has the higher score by 1 point.', 'Case X has the higher score by 1 point.', 'The two cases have equal scores.', 'Case Y has the higher score by 5 points.'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'For X, S=4×5+3×2=26. For Y, S=4×3+3×5=27. Therefore Y has the higher score by 1 point.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q056', section: 'General Studies Paper II (CSAT)', topic: 'Deductive reasoning', difficulty: 'medium', question: 'For a local resource-allocation exercise, Some clerks are translators. All translators know two languages. Which conclusion follows necessarily? Use the stated data as the complete decision rule for this case.', options: ['All clerks are translators.', 'All bilingual people are clerks.', 'No clerk knows two languages.', 'Some clerks know two languages.'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The clerks who are translators must have the property that all translators have: knowing two languages.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q057', section: 'General Studies Paper II (CSAT)', topic: 'Work rate', difficulty: 'hard', question: 'Eight clerks process 480 forms in 5 hours at a constant individual rate. After they have worked for 2 hours, two clerks leave. How many additional hours will the remaining six clerks need to finish the 480 forms?', options: ['3', '5', '6', '4'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Each clerk processes 480/(8×5)=12 forms per hour. In 2 hours, 8 clerks complete 192 forms, leaving 288. Six clerks process 72 forms per hour, so they need 288/72 = 4 additional hours.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q058', section: 'General Studies Paper II (CSAT)', topic: 'Interpersonal skills', difficulty: 'medium', question: 'A new employee asks the same procedural question twice after receiving a long manual. What is the best coaching response?', options: ['Repeat that the manual exists and refuse further help.', 'Walk through one real example, then ask the employee to perform the next example with feedback.', 'Complete all future tasks for the employee.', 'Criticize the employee in front of the team.'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Guided practice converts written guidance into usable skill while preserving the learner\'s responsibility to perform the task.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q059', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A road-safety team compared two junctions. One had more crashes, but it also carried almost three times as much traffic. The team therefore decided to compare crashes per ten thousand vehicles rather than raw crash counts.\n\nWhy is the revised comparison more informative?', options: ['It adjusts the crash measure for the different amount of traffic exposure.', 'It guarantees that both junctions will have the same crash rate.', 'It removes the need to count crashes accurately.', 'It proves that the busier junction is safer.'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A rate relative to traffic volume makes the two locations more comparable than raw counts alone.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q060', section: 'General Studies Paper II (CSAT)', topic: 'Work and time', difficulty: 'medium', question: 'A can complete a task in 10 days and B in 15 days. They work together for 3 days. What fraction of the task remains?', options: ['1/2', '1/3', '2/5', '3/5'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Combined daily work=1/10+1/15=1/6. In 3 days they complete 1/2, leaving 1/2.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q061', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'During a block-level service review in Odisha, A school cluster moved its parent meetings from weekday afternoons to alternating Saturday mornings after attendance records showed that many wage-earning parents could not leave work. Attendance improved, but the agenda and meeting length were unchanged.\n\nWhat is the most reasonable explanation for the higher attendance?\n\nThe district team used comparable working days and an unchanged definition of the recorded outcome. Read the account as a closed evidence set and choose the option that requires the fewest unstated assumptions.', options: ['The school reduced the number of meetings.', 'Parents were given shorter agendas.', 'All parents preferred longer meetings.', 'The revised timing removed an access barrier for some parents.'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The answer follows from the central relationship stated in the passage.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q062', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A school introduced a reading club. Attendance rose sharply during the first month, which also coincided with a school-wide festival that brought more students to campus after class. The coordinator avoided claiming that the club alone caused the rise.\n\nWhy is that caution justified?', options: ['The club could not possibly affect attendance.', 'Another event changed at the same time and could also have influenced attendance.', 'Coinciding events never affect interpretation.', 'A rise in attendance proves the festival had no effect.'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Because the festival is a plausible simultaneous influence, the observed rise cannot confidently be attributed to the club alone.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q063', section: 'General Studies Paper II (CSAT)', topic: 'Sets and inclusion-exclusion', difficulty: 'hard', question: 'In a survey of 100 households, 50 use service A, 45 use B and 40 use C. The numbers using both A and B, A and C, and B and C are 20, 18 and 15 respectively, and 8 use all three. How many households use none of the three services?', options: ['5', '8', '10', '12'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'By inclusion-exclusion, the union is 50+45+40−20−18−15+8 = 90. Therefore 100−90 = 10 households use none.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q064', section: 'General Studies Paper II (CSAT)', topic: 'Mensuration and divisibility', difficulty: 'medium', question: 'A rectangular notice board measuring 84 cm by 66 cm is to be covered exactly with the largest possible identical square labels, without cutting any label. How many labels are required?', options: ['154', '144', '160', '168'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The largest square side is gcd(84,66)=6 cm. The board needs 84/6=14 labels along one side and 66/6=11 along the other, for 14×11=154 labels.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q065', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A district store keeps critical spare parts in two separate rooms. This slightly increases inventory handling, but a leak in one room will not damage the entire stock.\n\nWhat trade-off is described?', options: ['Less handling effort in exchange for higher concentration risk.', 'Eliminating all inventory risk without any cost.', 'More handling effort in exchange for lower risk of a single incident destroying all critical stock.', 'Storing fewer spare parts to increase the chance of total loss.'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Separating the stock adds handling but reduces dependence on a single storage location.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q066', section: 'General Studies Paper II (CSAT)', topic: 'Average speed', difficulty: 'hard', question: 'A bus travels 120 km in 2 hours, stops for 30 minutes, then travels 90 km in 1.5 hours. What is its average speed including the stop?', options: ['60 km/h', '52.5 km/h', '56 km/h', '46.7 km/h'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Total distance=210 km; total elapsed time=4 h, so average speed=52.5 km/h.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q067', section: 'General Studies Paper II (CSAT)', topic: 'Problem solving', difficulty: 'hard', question: 'A courier has 75 minutes. Task X takes 25 minutes, Y takes 35 minutes and Z takes 30 minutes. X must be done before Y. Which set can definitely be completed within 75 minutes?', options: ['Y and Z and X', 'X and Z and Y', 'X, Y and Z', 'X and Y'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'X+Y=60 minutes and respects the order. All three tasks need 90 minutes.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q068', section: 'General Studies Paper II (CSAT)', topic: 'Decision making', difficulty: 'medium', question: 'A local office can process either 60 routine renewals or 20 urgent disability certificates today. A medical camp tomorrow depends on the disability certificates, while routine renewals remain valid for another month. Which allocation is most defensible?', options: ['Process only routine renewals because there are more of them.', 'Ignore the camp deadline.', 'Process neither category until capacity increases.', 'Prioritize the disability certificates needed for tomorrow\'s camp and schedule routine renewals within their remaining validity window.'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The disability certificates have a near-term dependency and higher time sensitivity, while routine renewals have slack.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q069', section: 'General Studies Paper II (CSAT)', topic: 'Piecewise work rate', difficulty: 'medium', question: 'A scanner processes 25 pages per minute for 12 minutes. Its rate then falls by 20%, and it runs for another 10 minutes. How many pages does it process in total?', options: ['500', '480', '520', '550'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The first phase gives 25×12 = 300 pages. After a 20% reduction, the rate is 20 pages per minute, adding 200 pages. Total = 500.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q070', section: 'General Studies Paper II (CSAT)', topic: 'Interpersonal skills', difficulty: 'medium', question: 'Two units compete for the same meeting room at the same time. Both have important work. What is the most constructive approach?', options: ['Compare actual constraints, identify whether either meeting can shift or split, and agree on a rule for the remaining conflict.', 'Let the louder unit take the room.', 'Cancel both meetings automatically.', 'Hide the booking calendar from both units.'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Jointly examining constraints and alternatives seeks a workable solution before resorting to arbitrary priority.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q071', section: 'General Studies Paper II (CSAT)', topic: 'Inference', difficulty: 'medium', question: 'In a review of eight service centres, exactly one centre exceeded its monthly target. Which conclusion must be true?', options: ['All eight centres met their targets.', 'The centre that exceeded its target had the highest total output.', 'No centre met its target exactly.', 'Seven centres did not exceed their targets.'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'If exactly one of eight centres exceeded its target, the other seven necessarily did not exceed their targets. They may have met the target exactly or fallen short.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q072', section: 'General Studies Paper II (CSAT)', topic: 'Remainders', difficulty: 'easy', question: 'A number leaves remainder 5 when divided by 12. What remainder does three times the number leave when divided by 12?', options: ['1', '5', '3', '9'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'If n≡5 mod 12, then 3n≡15≡3 mod 12.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q073', section: 'General Studies Paper II (CSAT)', topic: 'Cause and effect', difficulty: 'medium', question: 'After an office moved its help desk beside the entrance, visitors reached the correct counter more often. At the same time, new directional signs were installed throughout the building. Which conclusion is safest?', options: ['The improvement cannot be attributed to the desk relocation alone from these facts.', 'The relocation definitely caused all of the improvement.', 'The signs definitely had no effect.', 'Visitor guidance became worse.'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Two guidance changes occurred together, so the observations do not isolate the effect of the help-desk location.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q074', section: 'General Studies Paper II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A helpline measured average call duration and customer resolution. After agents were told to end calls faster, duration fell but repeat calls increased. The manager restored a target based on successful resolution rather than duration alone.\n\nWhich lesson is most directly supported?', options: ['Short calls always produce better service.', 'Repeat calls are unrelated to unresolved problems.', 'Performance should never be measured.', 'A performance metric can create poor incentives if it rewards speed without accounting for outcome quality.'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The duration-only target encouraged shorter calls while repeat calls rose, suggesting that the metric neglected resolution quality.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q075', section: 'General Studies Paper II (CSAT)', topic: 'Clock reasoning', difficulty: 'medium', question: 'How many minutes after 2:00 do the hour and minute hands first coincide?', options: ['About 10.91 minutes', '10 minutes', '12 minutes', '15 minutes'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'At 2:00 the gap is 60°. Relative speed is 5.5°/min, so time=60/5.5≈10.91 min.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q076', section: 'General Studies Paper II (CSAT)', topic: 'Decision logic', difficulty: 'medium', question: 'A rule says applications received after 5 p.m. are dated the next working day. An application arrives at 5:20 p.m. on Monday, and Tuesday is a working day. What date should it receive?', options: ['Wednesday', 'Tuesday', 'Monday', 'The previous Friday'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The application arrived after the cutoff, so the rule assigns the next working day, Tuesday.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q077', section: 'General Studies Paper II (CSAT)', topic: 'Calendar reasoning', difficulty: 'easy', question: 'If 1 March is a Wednesday in a non-leap year, what day of the week is 1 April?', options: ['Friday', 'Saturday', 'Sunday', 'Monday'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'March has 31 days, which shifts the weekday by 3 days: Wednesday → Saturday.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q078', section: 'General Studies Paper II (CSAT)', topic: 'Data interpretation', difficulty: 'easy', question: 'Monthly applications were Jan 400, Feb 460, Mar 430, Apr 510. Between which consecutive months was the largest absolute change?', options: ['January to February', 'February to March', 'All changes were equal', 'March to April'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Absolute changes are 60, 30 and 80; the largest is March to April.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q079', section: 'General Studies Paper II (CSAT)', topic: 'Problem solving', difficulty: 'medium', question: 'A store has 42 identical kits. Each full box holds 8 kits. What is the minimum number of boxes needed to pack all kits?', options: ['5', '6', '7', '8'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Five boxes hold only 40 kits, so a sixth box is required for the remaining two.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
  { id: 'b15-003-csat-q080', section: 'General Studies Paper II (CSAT)', topic: 'Pipes and cisterns', difficulty: 'medium', question: 'A pipe fills a tank in 8 hours, but with a leak open it takes 12 hours. How long would the leak alone take to empty a full tank?', options: ['18 hours', '20 hours', '30 hours', '24 hours'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Leak rate=1/8−1/12=1/24 tank per hour.', source: { kind: 'original', reference: 'OPSC OCS 2025 current cycle and GS-II rules', url: 'https://www.opsc.gov.in/Public/OPSC/Default.aspx', checkedOn: '2026-09-10' } },
];
